import { MIDI_KITS, type MidiPattern } from "@/lib/midi-kits";
import { kitById } from "@/lib/products";
import { SITE_NAME, SITE_URL, absoluteUrl } from "@/lib/site";
import catalogJson from "./pattern-catalog.json";

/**
 * Public pattern pages. Titles and copy are generated by
 * scripts/build-pattern-pages.py from the MIDI files plus lib/midi-kits.json.
 * Hand edits go in lib/pattern-overrides.json, then re-run that script.
 */

export type CatalogPattern = {
  id: string;
  libraryId: string;
  kitId: string;
  partId: string;
  genreSlug: string;
  slug: string;
  title: string;
  bpm: number;
  timeSignature: string | null;
  bars: number;
  hits: number;
  pitches: number;
  style: string;
  givenName: string | null;
  description: string;
  metaDescription: string;
  alsoIn: string[];
};

export type GenreInfo = {
  slug: string;
  name: string;
  kitId: string;
};

type Playable = MidiPattern & { partLabel: string };

const PART_LABEL: Record<string, string> = {
  hihat: "Hi-hats",
  "open-hat": "Open hats",
  snare: "Snares",
  kick: "Kicks",
  "808": "808s",
};

/** Hats first: the part producers reach for, matching the kit player. */
export const PART_ORDER = ["hihat", "open-hat", "snare", "kick", "808"] as const;

export const BPM_RANGES = [
  {
    slug: "under-120",
    label: "Under 120 BPM",
    min: 0,
    max: 119,
    description: "Slow and mid-tempo royalty-free MIDI drum patterns, under 120 BPM.",
  },
  {
    slug: "120-139",
    label: "120–139 BPM",
    min: 120,
    max: 139,
    description: "Trap-tempo royalty-free MIDI drum patterns from 120 to 139 BPM.",
  },
  {
    slug: "140-159",
    label: "140–159 BPM",
    min: 140,
    max: 159,
    description: "Fast trap and drill royalty-free MIDI drum patterns from 140 to 159 BPM.",
  },
  {
    slug: "160-plus",
    label: "160 BPM and up",
    min: 160,
    max: 400,
    description: "Uptempo royalty-free MIDI drum patterns at 160 BPM and above.",
  },
] as const;

export type BpmRange = (typeof BPM_RANGES)[number];

const GENRE_LIST = catalogJson.genres as GenreInfo[];
const RAW = catalogJson.patterns as CatalogPattern[];

const playable = new Map<string, Playable>();
for (const kit of MIDI_KITS) {
  for (const part of kit.parts) {
    for (const pattern of part.patterns) {
      playable.set(pattern.id, { ...pattern, partLabel: part.label });
    }
  }
}

export type PublicPattern = CatalogPattern & {
  genreName: string;
  partLabel: string;
  kitName: string;
  kitSlug: string;
  kitPrice: number;
  duration: number;
  peaks: number[];
  path: string;
};

function enrich(raw: CatalogPattern): PublicPattern {
  const play = playable.get(raw.id);
  const kit = kitById(raw.kitId);
  const genre = GENRE_LIST.find((g) => g.slug === raw.genreSlug);
  if (!play || !kit || !genre) {
    throw new Error(`Pattern ${raw.id} is missing kit, genre, or preview data`);
  }
  return {
    ...raw,
    genreName: genre.name,
    partLabel: PART_LABEL[raw.partId] ?? play.partLabel,
    kitName: kit.name,
    kitSlug: kit.slug,
    kitPrice: kit.price,
    duration: play.duration,
    peaks: play.peaks,
    path: `/midi/${raw.genreSlug}/${raw.slug}`,
  };
}

export const GENRES: GenreInfo[] = GENRE_LIST;
export const PATTERNS: PublicPattern[] = RAW.map(enrich);

const byId = new Map(PATTERNS.map((p) => [p.id, p]));
const byLibrary = new Map(PATTERNS.map((p) => [p.libraryId, p]));
const urls = new Set<string>();
for (const pattern of PATTERNS) {
  if (urls.has(pattern.path)) throw new Error(`Duplicate pattern URL ${pattern.path}`);
  urls.add(pattern.path);
  if (!bpmRangeFor(pattern.bpm)) throw new Error(`No BPM range for ${pattern.id} at ${pattern.bpm}`);
}

export function patternById(id: string) {
  return byId.get(id);
}

export function patternByLibraryId(id: string) {
  return byLibrary.get(id);
}

export function patternBySlug(genre: string, slug: string) {
  return PATTERNS.find((p) => p.genreSlug === genre && p.slug === slug);
}

export function genreBySlug(slug: string) {
  return GENRES.find((g) => g.slug === slug);
}

export function genreForKit(kitId: string) {
  return GENRES.find((g) => g.kitId === kitId);
}

export function patternsInGenre(slug: string) {
  return PATTERNS.filter((p) => p.genreSlug === slug);
}

export function bpmRangeFor(bpm: number) {
  return BPM_RANGES.find((range) => bpm >= range.min && bpm <= range.max);
}

export function bpmRangeBySlug(slug: string) {
  return BPM_RANGES.find((range) => range.slug === slug);
}

export function patternsInRange(range: BpmRange) {
  return PATTERNS.filter((p) => p.bpm >= range.min && p.bpm <= range.max);
}

export function patternGroups(patterns: PublicPattern[]) {
  return PART_ORDER.map((id) => ({
    id,
    label: patterns.find((p) => p.partId === id)?.partLabel ?? id,
    patterns: patterns.filter((p) => p.partId === id),
  })).filter((group) => group.patterns.length > 0);
}

export const genrePath = (genre: { slug: string }) => `/midi/${genre.slug}`;
export const bpmPath = (range: { slug: string }) => `/midi/bpm/${range.slug}`;
export const patternPath = (pattern: { path: string }) => pattern.path;

/** Same drum part, nearest tempo first, preferring the same style. */
export function relatedPatterns(pattern: PublicPattern, limit = 4) {
  return PATTERNS.filter((other) => other.id !== pattern.id && other.partId === pattern.partId)
    .sort((a, b) => {
      const tempo = Math.abs(a.bpm - pattern.bpm) - Math.abs(b.bpm - pattern.bpm);
      if (tempo !== 0) return tempo;
      return Number(b.genreSlug === pattern.genreSlug) - Number(a.genreSlug === pattern.genreSlug);
    })
    .slice(0, limit);
}

export function sameGroove(pattern: PublicPattern) {
  return pattern.alsoIn.map((id) => byId.get(id)).filter((p): p is PublicPattern => !!p);
}

export function genreStats(slug: string) {
  const genre = genreBySlug(slug);
  const kit = genre ? kitById(genre.kitId) : undefined;
  const list = patternsInGenre(slug);
  if (!genre || !kit || list.length === 0) return undefined;
  const bpms = list.map((p) => p.bpm);
  return {
    genre,
    kit,
    patterns: list,
    minBpm: Math.min(...bpms),
    maxBpm: Math.max(...bpms),
  };
}

const isoDuration = (seconds: number) => `PT${Math.max(1, Math.round(seconds))}S`;

export function patternJsonLd(pattern: PublicPattern) {
  const url = absoluteUrl(pattern.path);
  const genreUrl = absoluteUrl(genrePath(pattern));
  const kitUrl = absoluteUrl(`/kits/${pattern.kitSlug}`);
  return [
    {
      "@context": "https://schema.org",
      "@type": "MusicRecording",
      name: pattern.title,
      description: pattern.metaDescription,
      url,
      duration: isoDuration(pattern.duration),
      genre: pattern.genreName,
      byArtist: { "@type": "Organization", name: SITE_NAME, url: SITE_URL },
      recordingOf: {
        "@type": "MusicComposition",
        name: pattern.title,
        composer: { "@type": "Organization", name: SITE_NAME },
      },
      additionalProperty: [
        { "@type": "PropertyValue", name: "Tempo", value: `${pattern.bpm} BPM` },
        ...(pattern.timeSignature
          ? [{ "@type": "PropertyValue", name: "Time signature", value: pattern.timeSignature }]
          : []),
      ],
      offers: {
        "@type": "Offer",
        price: pattern.kitPrice.toFixed(2),
        priceCurrency: "USD",
        availability: "https://schema.org/InStock",
        url: kitUrl,
        description: `Included in the ${pattern.kitName} MIDI kit. This file can also be unlocked with 1 credit.`,
      },
    },
    {
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      itemListElement: [
        { "@type": "ListItem", position: 1, name: "Home", item: SITE_URL },
        { "@type": "ListItem", position: 2, name: "MIDI patterns", item: absoluteUrl("/midi") },
        { "@type": "ListItem", position: 3, name: pattern.genreName, item: genreUrl },
        { "@type": "ListItem", position: 4, name: pattern.title, item: url },
      ],
    },
  ];
}

export function patternListJsonLd(name: string, description: string, url: string, patterns: PublicPattern[]) {
  return {
    "@context": "https://schema.org",
    "@type": "CollectionPage",
    name,
    description,
    url,
    mainEntity: {
      "@type": "ItemList",
      numberOfItems: patterns.length,
      itemListElement: patterns.map((pattern, index) => ({
        "@type": "ListItem",
        position: index + 1,
        url: absoluteUrl(pattern.path),
        name: pattern.title,
      })),
    },
  };
}
